INSERT INTO incidents (title, description, severity, status, reported_by, assigned_to, reported_at) VALUES
('An unencrypted USB drive with order exports went missing from the Marketing office','Reported by the Marketing team on 2026-07-08. An unencrypted USB drive with order exports went missing from the Marketing office. Login to the CRM was recorded from an unrecognized location using Jerome Cruz''s credentials.','low','open',3,NULL,now() - interval '28 days'),
('A team used customer purchase data for a purpose not covered by the privacy notice','IT security was notified immediately. A team used customer purchase data for a purpose not covered by the privacy notice. Reported by the IT team on 2026-09-02. Customers reported SMS messages claiming to be from Acme Retail asking for OTP codes.','medium','open',3,4,now() - interval '27 days'),
('An employee left their work phone in a restaurant and it was not recovered','Initial assessment is ongoing. An employee left their work phone in a restaurant and it was not recovered. Bea Navarro reported a company laptop lost in a taxi; it may contain customer reports.','medium','investigating',3,4,now() - interval '26 days'),
('A partner reported receiving a file with unmasked customer addresses','A partner reported receiving a file with unmasked customer addresses. No confirmation yet whether customer data was affected. A spreadsheet containing 2850 customer contact details was found on a public file-sharing link.','high','contained',3,NULL,now() - interval '25 days'),
('Access permissions on the reports folder were set to everyone in the company','Access permissions on the reports folder were set to everyone in the company. Initial assessment is ongoing.','critical','resolved',3,4,now() - interval '24 days'),
('Customers reported SMS messages claiming to be from Acme Retail asking for OTP codes','Customers reported SMS messages claiming to be from Acme Retail asking for OTP codes. This may require notification depending on impact.','medium','closed',3,4,now() - interval '23 days'),
('An email with an attachment of order history was sent to the wrong external recipient','An email with an attachment of order history was sent to the wrong external recipient. The affected systems were noted in the ticket. IT security was notified immediately.','high','investigating',3,NULL,now() - interval '22 days'),
('Debug logging was left on in production and wrote full customer records to log files','Debug logging was left on in production and wrote full customer records to log files. The affected systems were noted in the ticket. The incident was escalated to the DPO for review.','low','open',3,4,now() - interval '21 days'),
('A fake login page mimicking our HR portal was sent to 2545 employees','A fake login page mimicking our HR portal was sent to 2545 employees. Initial assessment is ongoing. The affected systems were noted in the ticket. Reported by the Customer Service team on 2026-08-03. An employee clicked a link in a fraudulent invoice email and entered credentials.','medium','open',3,4,now() - interval '20 days'),
('Staff sent customer details through a personal messaging app against company policy','Staff sent customer details through a personal messaging app against company policy. A backup hard drive could not be located after an office move. The affected systems were noted in the ticket.','medium','investigating',3,NULL,now() - interval '19 days'),
('Internal report with customer names was uploaded to a personal cloud drive and shared...','Internal report with customer names was uploaded to a personal cloud drive and shared publicly. Reported by the Customer Service team on 2026-07-21. No confirmation yet whether customer data was affected. The affected systems were noted in the ticket.','high','contained',3,4,now() - interval '18 days'),
('Customer emails and phone numbers were posted in an online forum, apparently from our...','Customer emails and phone numbers were posted in an online forum, apparently from our export. The affected systems were noted in the ticket.','critical','resolved',3,4,now() - interval '17 days'),
('A contractor viewed payment records without an approved ticket','IT security was notified immediately. This may require notification depending on impact. A contractor viewed payment records without an approved ticket.','medium','closed',3,NULL,now() - interval '16 days'),
('Printed customer forms were left unattended on a desk overnight','Printed customer forms were left unattended on a desk overnight. No confirmation yet whether customer data was affected. Staff sent customer details through a personal messaging app against company policy.','high','investigating',3,4,now() - interval '15 days'),
('An API endpoint returned more fields than intended after a deployment','An API endpoint returned more fields than intended after a deployment. A spoofed domain sent emails asking staff to verify payroll information. IT security was notified immediately. The incident was escalated to the DPO for review. Further details to follow after investigation.','low','open',3,4,now() - interval '14 days'),
('A team used customer purchase data for a purpose not covered by the privacy notice','A team used customer purchase data for a purpose not covered by the privacy notice. The incident was escalated to the DPO for review. TLS certificate expired and the customer portal briefly served pages over plain HTTP.','medium','open',3,NULL,now() - interval '13 days'),
('Printed customer forms were left unattended on a desk overnight','IT security was notified immediately. Printed customer forms were left unattended on a desk overnight.','medium','investigating',3,4,now() - interval '12 days'),
('TLS certificate expired and the customer portal briefly served pages over plain HTTP','TLS certificate expired and the customer portal briefly served pages over plain HTTP. Reported by the Logistics team on 2026-07-27.','high','contained',3,4,now() - interval '11 days'),
('A fake login page mimicking our HR portal was sent to 139 employees','Reported by the Marketing team on 2026-08-07. Initial assessment is ongoing. A fake login page mimicking our HR portal was sent to 139 employees.','critical','resolved',3,NULL,now() - interval '10 days'),
('Internal report with customer names was uploaded to a personal cloud drive and shared...','IT security was notified immediately. Internal report with customer names was uploaded to a personal cloud drive and shared publicly. Initial assessment is ongoing.','medium','closed',3,4,now() - interval '9 days'),
('A fake login page mimicking our HR portal was sent to 3670 employees','A fake login page mimicking our HR portal was sent to 3670 employees. No confirmation yet whether customer data was affected. A former staff member''s account was still active and was used to open customer records.','high','investigating',3,4,now() - interval '8 days'),
('A team used customer purchase data for a purpose not covered by the privacy notice','Further details to follow after investigation. A team used customer purchase data for a purpose not covered by the privacy notice.','low','open',3,NULL,now() - interval '7 days'),
('Login to the CRM was recorded from an unrecognized location using Ramon Castillo''s...','Login to the CRM was recorded from an unrecognized location using Ramon Castillo''s credentials. No confirmation yet whether customer data was affected. This may require notification depending on impact.','medium','open',3,4,now() - interval '6 days'),
('Grace Santos reported a company laptop lost in a taxi','No confirmation yet whether customer data was affected. The incident was escalated to the DPO for review. Initial assessment is ongoing. Grace Santos reported a company laptop lost in a taxi; it may contain customer reports.','medium','investigating',3,4,now() - interval '5 days'),
('A mobile phone with access to the CRM app was stolen at a mall','Reported by the Marketing team on 2026-09-23. A mobile phone with access to the CRM app was stolen at a mall.','high','contained',3,NULL,now() - interval '4 days'),
('A fake login page mimicking our HR portal was sent to 2140 employees','Reported by the Store Operations team on 2026-07-25. A fake login page mimicking our HR portal was sent to 2140 employees. Further details to follow after investigation. The affected systems were noted in the ticket.','critical','resolved',3,4,now() - interval '3 days'),
('Access permissions on the reports folder were set to everyone in the company','IT security was notified immediately. This may require notification depending on impact. The affected systems were noted in the ticket. Access permissions on the reports folder were set to everyone in the company. A tablet used for in-store sign-ups was misplaced during inventory.','medium','closed',3,4,now() - interval '2 days'),
('An employee left their work phone in a restaurant and it was not recovered','Reported by the Logistics team on 2026-07-27. IT security was notified immediately. An employee left their work phone in a restaurant and it was not recovered. The incident was escalated to the DPO for review.','high','investigating',3,NULL,now() - interval '1 days');
